function filterFinanceData(){const searchQuery=document.getElementById("finance-search").value.toLowerCase().replace(/[^0-9a-z]/g,""),selectedYear=document.getElementById("filter-year").value,selectedDivision=document.getElementById("filter-division").value,tableRows=document.querySelectorAll("#finance-table-body tr");let visibleRowsCount=0;tableRows.forEach(row=>{if(row.cells.length<5)return;const rowYear=row.getAttribute("data-year"),rowDivision=row.getAttribute("data-division"),rowType=row.getAttribute("data-type"),descriptionText=row.cells[1].textContent.toLowerCase(),rawAmountText=row.cells[4].textContent.toLowerCase().replace(/[^0-9a-z]/g,""),matchYear="all"===selectedYear||rowYear===selectedYear,matchDivision="all"===selectedDivision||rowDivision===selectedDivision,matchSearch=descriptionText.includes(searchQuery)||rowType.includes(searchQuery)||rawAmountText.includes(searchQuery);matchYear&&matchDivision&&matchSearch?(row.classList.remove("hidden"),visibleRowsCount++):row.classList.add("hidden")});const emptyState=document.getElementById("finance-empty-state");0===visibleRowsCount?emptyState.classList.remove("hidden"):emptyState.classList.add("hidden")}function openFinanceModal(){const modal=document.getElementById("finance-modal"),content=document.getElementById("modal-content");modal&&(modal.classList.remove("hidden"),modal.classList.add("flex"),setTimeout(()=>{content.classList.remove("scale-95","opacity-0"),content.classList.add("scale-100","opacity-100")},10))}function closeFinanceModal(){const modal=document.getElementById("finance-modal"),content=document.getElementById("modal-content");modal&&(content.classList.remove("scale-100","opacity-100"),content.classList.add("scale-95","opacity-0"),setTimeout(()=>{modal.classList.remove("flex"),modal.classList.add("hidden")},300))}function openEditFinanceModal(button){const modal=document.getElementById("finance-edit-modal"),content=document.getElementById("edit-modal-content"),form=document.getElementById("edit-finance-form"),id=button.getAttribute("data-id"),tanggal=button.getAttribute("data-tanggal"),keterangan=button.getAttribute("data-keterangan"),divisi=button.getAttribute("data-divisi"),jenis=button.getAttribute("data-jenis"),nominal=button.getAttribute("data-nominal");document.getElementById("edit-tanggal").value=tanggal,document.getElementById("edit-keterangan").value=keterangan,document.getElementById("edit-jenis").value=jenis,document.getElementById("edit-nominal").value=nominal;const divisiDisplay=document.getElementById("edit-divisi-display");if(divisiDisplay){const divisiNames={inti:"Manajemen Inti",humas:"Divisi Humas",artmedia:"Divisi Artmedia",olahraga:"Divisi Olahraga",agama:"Divisi Agama"};divisiDisplay.value=divisiNames[divisi]||divisi,document.getElementById("edit-divisi").value=divisi}else document.getElementById("edit-divisi").value=divisi;window.syncCustomUI&&window.syncCustomUI();form.action=`/keuangan/${id}`,modal&&(modal.classList.remove("hidden"),modal.classList.add("flex"),setTimeout(()=>{content.classList.remove("scale-95","opacity-0"),content.classList.add("scale-100","opacity-100")},10))}function closeEditFinanceModal(){const modal=document.getElementById("finance-edit-modal"),content=document.getElementById("edit-modal-content");modal&&(content.classList.remove("scale-100","opacity-100"),content.classList.add("scale-95","opacity-0"),setTimeout(()=>{modal.classList.remove("flex"),modal.classList.add("hidden")},300))}function confirmDeleteFinance(id){Swal.fire({title:"Apakah Anda yakin?",text:"Data transaksi ini akan dihapus permanen dari arsip kas OSIS!",icon:"warning",showCancelButton:!0,background:"#ffffff",color:"#1e293b",confirmButtonColor:"#df1c24",cancelButtonColor:"#94a3b8",confirmButtonText:"Ya, Hapus!",cancelButtonText:"Batal"}).then(result=>{result.isConfirmed&&document.getElementById(`delete-form-${id}`).submit()})}